// Package gen provides protobuf generated types.
//
// Component Contract (FR10):
// - What it does: Generated API and structures for manifest protobuf schemas. This package is an implementation detail of the manifest component.
// - What it requires: Protobuf unmarshaler to populate the models.
// - What it provides: Protoreflect-enabled struct types for parsing manifests.
// - Ambient Authority: This component is clean of filesystem/network ambient authority but leverages REFLECT, RUNTIME, SYSTEM_CALLS, and UNSAFE_POINTER internally via protobuf unmarshaling.
syntax = "proto3";

package archcontracts.v1;

option go_package = "github.com/ono-sendai-labs/architectural-contracts/go/internal/manifest/gen;gen";

// A component's manifest, stored as component.textproto at the COMPONENT ROOT.
// When members is empty, the component consists of all Go packages under the
// manifest file's directory (FR1). Otherwise, members declares the packages
// the component owns; the interface package is an implicit member. Interface
// file paths are relative to the component root (C9). There is no contract
// field: the component's informal contract is doc-comment prose in its
// interface files (FR10).
message Component {
  string name = 1;                          // logical component name
  repeated string interface_files = 2;      // .go files holding the public surface, relative to the
                                            // component root; multi-package components use subdir
                                            // paths (store/api.go)
  repeated ComponentDependency component_dependencies = 3;
  // Reserved: retired field `absorbed_dependencies`. Never reuse.
  reserved 4;
  reserved "absorbed_dependencies";
  // Reserved: retired self-declared verification fields `own_check_runs`
  // (author claim about its own check) and `certification_reference` (author
  // claim about external certification). Verification provenance is derived
  // structurally from producer and report artifacts, not author claims.
  // Never reuse numbers 8 or 9, or either name.
  reserved 8, 9;
  reserved "own_check_runs", "certification_reference";
  repeated string declared_authority = 5;   // capability names, validated at parse time against the
                                            // known capability set (C11); empty = ambient-authority-free

  // Member packages: the code this component is responsible for and analyzes
  // as roots. Entries are literal import paths; glob metacharacters are
  // rejected at parse time. The interface package is implicitly a member and
  // need not be listed.
  //
  // Empty means FR1: every package under the component root.
  repeated string members = 6;

  // How this component's exposed interface is determined.
  InterfaceStyle interface_style = 7;

  // Whether this component's authority was verified by analysis (DECLARED, the
  // backward-compatible default) or is unknown because the component has not
  // been analysed. When UNKNOWN, declared_authority must be empty: unknown
  // means the component could use any ambient authority, not that it uses none.
  Authority authority = 10;
}

// Authority distinguishes a verified declaration of ambient authority from an
// unanalysed component. An empty declared_authority list under DECLARED means
// "checked, uses nothing"; UNKNOWN must never be represented that way.
enum Authority {
  // The component's authority is declared in declared_authority and verified
  // by analysis. This is the backward-compatible default.
  //
  // The value names deliberately match the manifest spelling (design R10:
  // `authority: UNKNOWN` in textproto), without an enum-name prefix.
  DECLARED = 0;

  // The component has not been analysed; its authority is unknown rather than
  // empty. declared_authority must be empty.
  UNKNOWN = 1;
}

// InterfaceStyle distinguishes a component that declares its surface from one
// that wraps code never written to have an architectural interface.
enum InterfaceStyle {
  // The interface is declared by interface_files. This is the backward-
  // compatible default.
  INTERFACE_STYLE_UNSPECIFIED = 0;

  // The interface is every exported symbol of every member package.
  INTERFACE_STYLE_PACKAGE_SURFACE = 1;
}

message ComponentDependency {
  string name = 1;                          // referenced component's name; must match the `name`
                                            // in the resolved manifest (C12)
  string manifest = 2;                      // path to that component's manifest, relative to the
                                            // DECLARING manifest's directory; the resolved manifest's
                                            // own directory is the dependency's component root and the
                                            // source of truth for its declared interface symbols
                                            // (interface packages are DERIVED — packages containing
                                            // interface files, C10)
  // The emitter injected this edge rather than an author writing it. An
  // unused auto-attached edge is not the author's mistake.
  bool auto_attached = 3;
}

